-- Generated by scripts/sync-supabase-migration.cjs.
-- Edit docs/supabase/schema.sql, then run npm run supabase:migration:sync.

-- Project Odysseus initial Supabase LMS schema plan.
-- This is additive planning SQL for a Supabase project, not yet wired into the existing Prisma migrations.

create extension if not exists "pgcrypto";

-- Postgres has no `create type ... if not exists`; guarded via pg_type check
-- (matches this file's established guarded-enum convention) so this file can
-- be safely re-applied against an already-migrated database, not just a fresh one.
do $$
begin
  if not exists (select 1 from pg_type where typname = 'user_role') then
    create type public.user_role as enum ('student', 'tutor', 'admin', 'parent', 'ngo_partner');
  end if;
  if not exists (select 1 from pg_type where typname = 'record_status') then
    create type public.record_status as enum ('active', 'inactive', 'pending', 'approved', 'suspended');
  end if;
  if not exists (select 1 from pg_type where typname = 'assignment_status') then
    create type public.assignment_status as enum ('draft', 'published', 'closed', 'archived');
  end if;
  if not exists (select 1 from pg_type where typname = 'submission_status') then
    create type public.submission_status as enum ('not_submitted', 'submitted', 'marked', 'returned');
  end if;
  if not exists (select 1 from pg_type where typname = 'payment_status') then
    create type public.payment_status as enum ('pending', 'paid', 'overdue', 'voided');
  end if;
end
$$;

create table if not exists public.profiles (
  id uuid primary key default gen_random_uuid(),
  auth_user_id uuid not null unique references auth.users(id) on delete cascade,
  full_name text not null,
  email text not null unique,
  phone text,
  role public.user_role not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.ngo_partners (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  contact_person text,
  contact_email text,
  contact_phone text,
  location text,
  notes text,
  created_at timestamptz not null default now()
);

create table if not exists public.students (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid not null unique references public.profiles(id) on delete cascade,
  grade text,
  school text,
  parent_name text,
  parent_contact text,
  ngo_partner_id uuid references public.ngo_partners(id),
  status public.record_status not null default 'pending',
  created_at timestamptz not null default now()
);

-- Production's students table (created before this file's current definition
-- existed) carries several extra columns not modeled here at all --
-- full_name, guardian_name/phone/relationship/email/address, notes,
-- subjects_json, partner_affiliation -- leftovers from an earlier schema
-- iteration, since profiles.full_name is this schema's actual source of
-- truth for a person's name. Only full_name was NOT NULL with no default,
-- which silently blocked every insert into students (nothing had actually
-- attempted a new students row anywhere in this migration until
-- admin-invite-user's functional verification surfaced it -- the table had
-- zero rows in production, so this is a pure constraint fix, not a backfill).
do $$
begin
  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'students' and column_name = 'full_name' and is_nullable = 'NO'
  ) then
    alter table public.students alter column full_name drop not null;
  end if;
end
$$;

