drop policy if exists "tutors_select_self_or_admin" on public.tutors;
create policy "tutors_select_self_or_admin"
on public.tutors for select
using (
  public.is_platform_admin()
  or profile_id = public.current_profile_id()
  or id in (
    select tsa.tutor_id
